import { cleanup, render, screen, within } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { Transcript } from "./Transcript";
import { emptyRun } from "./runReducer";
import type { RunState, Segment } from "./types";
import { useProviderStore, type Connection } from "@/components/providers/providerStore";
import { useChatProviderStore } from "@/store/chatProviderStore";

function conn(overrides: Partial<Connection>): Connection {
  return {
    id: "c",
    provider: "anthropic",
    label: "Anthropic",
    residence: "cloud",
    endpoint: "https://api.anthropic.com",
    secret: null,
    health: "live",
    detail: "",
    probes: [],
    facts: [],
    models: [],
    route: [],
    routeSort: "price",
    allowed: [],
    enabled: true,
    lastProbe: "",
    ...overrides,
  };
}

function seg(overrides: Partial<Segment>): Segment {
  return {
    nodeId: "n",
    type: "agent",
    label: "Node",
    adapter: "claude",
    model: "claude-sonnet-5",
    intrinsic: false,
    state: "done",
    phase: "",
    phaseDetail: "",
    blocks: [],
    ...overrides,
  };
}

const ANTHROPIC = conn({ id: "an", label: "Anthropic" });
const OLLAMA = conn({ id: "ol", label: "Ollama local" });

/**
 * A four-node completed run: one direct-path node with no connection at all,
 * one pinned to the same connection the composer would pick by default, one
 * deliberately pinned elsewhere (the genuine mismatch), and one that errored
 * before finishing. Mirrors a real harness_done-terminated RunState rather
 * than a trivial stub — token/latency values are chosen to avoid
 * floating-point rounding boundaries in the formatters under test.
 */
function makeRun(overrides: Partial<RunState> = {}): RunState {
  const plan: Segment[] = [
    seg({ nodeId: "po", label: "PO", tokens: 1200, latencyMs: 2200, state: "done" }),
    seg({ nodeId: "dev", label: "Dev", tokens: 3400, latencyMs: 5100, state: "done", connectionId: "an" }),
    seg({ nodeId: "qa", label: "QA", tokens: 900, latencyMs: 1300, state: "done", connectionId: "ol" }),
    seg({ nodeId: "sec", label: "Security", tokens: 100, state: "error", error: "boom" }),
  ];
  return {
    ...emptyRun,
    runId: "r1",
    status: "complete",
    startedAt: 1_000,
    endedAt: 10_400,
    plan,
    totals: { tokens: 1200 + 3400 + 900 + 100, nodesRun: 4, elapsedMs: 9_400 },
    ...overrides,
  };
}

describe("Transcript — trajectory breakdown", () => {
  beforeEach(() => {
    useProviderStore.setState({ connections: [ANTHROPIC, OLLAMA] });
    useChatProviderStore.setState({ chosenId: "an" }); // composer's current default
  });

  afterEach(() => {
    cleanup();
    useProviderStore.setState({ connections: [] });
    useChatProviderStore.setState({ chosenId: null });
  });

  it("renders a rollup of real run totals, preferring the backend-measured elapsed over a stale live tick", () => {
    render(<Transcript run={makeRun()} onResolve={() => {}} elapsed={500} />);

    // totals.elapsedMs (9400ms -> "9.4s") must win over the live `elapsed`
    // prop (500ms -> "0.5s") once harness_done has reported a real figure.
    expect(screen.getByText("9.4s")).toBeTruthy();
    expect(screen.queryByText("0.5s")).toBeNull();
    expect(screen.getByText("5.6k")).toBeTruthy(); // fmtTokens(5600)
    expect(screen.getByText("4/4")).toBeTruthy();
  });

  it("shows a live ticking elapsed while the run has not yet reported a backend-measured total", () => {
    const run = makeRun({ status: "running", totals: { tokens: 900, nodesRun: 1, elapsedMs: 0 } });
    render(<Transcript run={run} onResolve={() => {}} elapsed={1_500} />);
    expect(screen.getByText("1.5s")).toBeTruthy();
  });

  it("renders a safe fallback when the backend sends an unknown node type", () => {
    const unknown = seg({
      nodeId: "future-node",
      label: "Future node",
      type: "future-type" as Segment["type"],
    });
    render(<Transcript run={makeRun({ plan: [unknown], totals: { tokens: 0, nodesRun: 1, elapsedMs: 100 } })} onResolve={() => {}} />);

    expect(screen.getAllByText("Future node")).toHaveLength(2);
    expect(screen.getByText(/future-type/)).toBeTruthy();
  });

  it("labels the rollup as measured once harness_done has confirmed the totals", () => {
    render(<Transcript run={makeRun()} onResolve={() => {}} elapsed={500} />);
    const label = screen.getByText("measured");
    expect(label.getAttribute("title")).toMatch(/backend/i);
    expect(screen.queryByText("estimated")).toBeNull();
  });

  it("labels the rollup as estimated while the client is still the only one counting", () => {
    const run = makeRun({ status: "running", totals: { tokens: 900, nodesRun: 1, elapsedMs: 0 } });
    render(<Transcript run={run} onResolve={() => {}} elapsed={1_500} />);
    const label = screen.getByText("estimated");
    expect(label.getAttribute("title")).toMatch(/local/i);
    expect(screen.queryByText("measured")).toBeNull();
  });

  it("flips the label from estimated to measured when the backend total arrives mid-view", () => {
    const running = makeRun({ status: "running", totals: { tokens: 900, nodesRun: 1, elapsedMs: 0 } });
    const { rerender } = render(<Transcript run={running} onResolve={() => {}} elapsed={1_500} />);
    expect(screen.getByText("estimated")).toBeTruthy();
    rerender(<Transcript run={makeRun()} onResolve={() => {}} elapsed={1_500} />);
    expect(screen.getByText("measured")).toBeTruthy();
    expect(screen.queryByText("estimated")).toBeNull();
  });

  it("gives each completed node its own legible latency + token row, not just the aggregate", () => {
    render(<Transcript run={makeRun()} onResolve={() => {}} elapsed={500} />);
    const table = screen.getByRole("table");

    const poRow = within(table).getByText("PO").closest("tr")!;
    const devRow = within(table).getByText("Dev").closest("tr")!;
    const qaRow = within(table).getByText("QA").closest("tr")!;

    expect(within(poRow).getByText("2.20s")).toBeTruthy();
    expect(within(poRow).getByText("1.2k")).toBeTruthy();

    expect(within(devRow).getByText("5.10s")).toBeTruthy();
    expect(within(devRow).getByText("3.4k")).toBeTruthy();

    expect(within(qaRow).getByText("1.30s")).toBeTruthy();
    expect(within(qaRow).getByText("900")).toBeTruthy();
  });

  it("shows an honest placeholder, not a fabricated latency, for a node that errored before finishing", () => {
    render(<Transcript run={makeRun()} onResolve={() => {}} elapsed={500} />);
    const table = screen.getByRole("table");
    const secRow = within(table).getByText("Security").closest("tr")!;

    expect(within(secRow).getByText("—")).toBeTruthy();
    expect(within(secRow).getByText("100")).toBeTruthy(); // tokens were still real
  });

  it("badges only the node whose pinned connection genuinely differs from the composer's current default", () => {
    render(<Transcript run={makeRun()} onResolve={() => {}} elapsed={500} />);
    const table = screen.getByRole("table");

    const qaRow = within(table).getByText("QA").closest("tr")!;
    expect(within(qaRow).getByText(/pinned/i)).toBeTruthy();
    expect(within(qaRow).getByText(/Ollama local/)).toBeTruthy();

    // Same connection as the default: no badge.
    const devRow = within(table).getByText("Dev").closest("tr")!;
    expect(within(devRow).queryByText(/pinned/i)).toBeNull();

    // No connectionId at all (the harness-off direct path): no badge.
    const poRow = within(table).getByText("PO").closest("tr")!;
    expect(within(poRow).queryByText(/pinned/i)).toBeNull();

    // Errored, no connectionId either: no badge.
    const secRow = within(table).getByText("Security").closest("tr")!;
    expect(within(secRow).queryByText(/pinned/i)).toBeNull();
  });

  it("never badges a pin when the composer itself has no resolvable default to compare against", () => {
    useProviderStore.setState({ connections: [] });
    useChatProviderStore.setState({ chosenId: null });

    render(<Transcript run={makeRun()} onResolve={() => {}} elapsed={500} />);
    const table = screen.getByRole("table");

    // QA is pinned to "ol", which is real, but there is nothing honest to
    // call "the default" right now — flagging every pin against nothing
    // configured would be noise, not signal.
    const qaRow = within(table).getByText("QA").closest("tr")!;
    expect(within(qaRow).queryByText(/pinned/i)).toBeNull();
  });

  it("renders no rollup at all for a run that has not started — no fabricated zeros", () => {
    render(<Transcript run={emptyRun} onResolve={() => {}} elapsed={0} />);
    expect(screen.queryByText("elapsed")).toBeNull();
    expect(screen.queryByText("tok")).toBeNull();
    expect(screen.queryByRole("table")).toBeNull();
  });
});

src/components/agent/ChatComposer.test.t.source:
import { useRef, useState } from "react";
import { afterEach, beforeEach, expect, it, vi } from "vitest";
import { cleanup, fireEvent, render, screen } from "@testing-library/react";
import { useShellStore } from "@/components/shell/shellStore";
import { useThreadStore } from "@/store/threadStore";
import { ChatComposer } from "./ChatComposer";
const send = vi.fn();
function Composer({ skills = {}, live = false }: { skills?: unknown; live?: boolean }) {
  const [value, setValue] = useState("");
  const ref = useRef<HTMLTextAreaElement>(null);
  return <ChatComposer value={value} onChange={setValue} onSend={send} inputRef={ref} skills={skills} live={live} />;
}
function type(value: string) {
  const input = screen.getByRole("textbox", { name: "Message OpenHarness" }) as HTMLTextAreaElement;
  input.focus(); fireEvent.change(input, { target: { value } }); return input;
}
beforeEach(() => {
  vi.clearAllMocks();
  HTMLElement.prototype.scrollIntoView = vi.fn();
  useShellStore.setState({ section: "chats", libraryOpen: false, keymapOpen: false });
  useThreadStore.setState({ activeThreadId: null, threads: [], messagesByThread: {} });
});
afterEach(cleanup);
it("opens on slash, keeps input focus and executes the highlighted action with arrows and Enter", () => {
  render(<Composer />); const input = type("/");
  expect(screen.getByRole("listbox", { name: "Commands and skills" })).toBeTruthy();
  expect(screen.getAllByRole("option")).toHaveLength(6);
  fireEvent.keyDown(input, { key: "ArrowDown" });
  const option = screen.getByRole("option", { name: /\/studio/ });
  expect(input.getAttribute("aria-activedescendant")).toBe(option.id);
  expect(document.activeElement).toBe(input);
  fireEvent.keyDown(input, { key: "Enter" });
  expect(useShellStore.getState().section).toBe("studio");
  expect(input.value).toBe(""); expect(send).not.toHaveBeenCalled();
});
it("filters commands and selects with Tab without sending slash text", () => {
  render(<Composer />); const input = type("/pro");
  expect(screen.getAllByRole("option")).toHaveLength(1);
  fireEvent.keyDown(input, { key: "Tab" });
  expect(useShellStore.getState().section).toBe("providers");
  expect(input.value).toBe(""); expect(send).not.toHaveBeenCalled();
});
it("Escape dismisses without erasing, and ordinary URLs or paths do not open a menu", () => {
  render(<Composer />); const input = type("/studio");
  fireEvent.keyDown(input, { key: "Escape" });
  expect(screen.queryByRole("listbox")).toBeNull(); expect(input.value).toBe("/studio");
  type("https://example.com/path"); expect(screen.queryByRole("listbox")).toBeNull();
  type("/usr/local"); expect(screen.queryByRole("listbox")).toBeNull();
  fireEvent.keyDown(input, { key: "Enter", ctrlKey: true }); expect(send).toHaveBeenCalledOnce();
});
it("inserts only an actual bundled skill as editable plain text, without executing it", () => {
  const content = "# Review\nCheck the diff. <script>untrusted()</script>";
  render(<Composer skills={{ review: content, empty: "", malformed: { code: "no" } }} />);
  const input = type("/skill:rev");
  fireEvent.click(screen.getByRole("option", { name: /\/skill:review/ }));
  expect(input.value).toBe(content); expect(document.activeElement).toBe(input);
  expect(screen.queryByRole("listbox")).toBeNull(); expect(document.querySelector("script")).toBeNull();
  expect(send).not.toHaveBeenCalled();
});
it("unknown commands do not submit, and IME Enter does not choose an action", () => {
  render(<Composer />); const input = type("/nonexistent");
  expect(screen.getByRole("status").textContent).toContain("No matching commands");
  fireEvent.keyDown(input, { key: "Enter", ctrlKey: true }); expect(send).not.toHaveBeenCalled();
  type("/studio"); fireEvent.keyDown(input, { key: "Enter", isComposing: true });
  expect(useShellStore.getState().section).toBe("chats"); expect(input.value).toBe("/studio");
});
it("keeps commands unavailable during a running turn", () => {
  render(<Composer live />); const input = type("/new");
  expect(screen.getByRole("option").getAttribute("aria-disabled")).toBe("true");
  fireEvent.keyDown(input, { key: "Enter" });
  expect(input.value).toBe("/new"); expect(send).not.toHaveBeenCalled();
});
it("disables the composer while a run is live — Ctrl+Enter must not silently no-op", () => {
  // Surfaced live: a person typed a new message during a run, pressed
  // Ctrl+Enter, and nothing happened with no explanation — onSend() (bound
  // to a canStart-gated handler upstream) already refused to start a second
  // run, but gave no feedback. The composer itself must make this obvious.
  render(<Composer live />);
  const input = screen.getByRole("textbox", { name: "Message OpenHarness" }) as HTMLTextAreaElement;
  expect(input.disabled).toBe(true);
  expect(input.placeholder).toMatch(/waiting|stop/i);
  fireEvent.keyDown(input, { key: "Enter", ctrlKey: true });
  expect(send).not.toHaveBeenCalled();
});
it("new chat retains saved messages and creates no empty thread", () => {
  const id = useThreadStore.getState().createThread("Existing chat");
  useThreadStore.getState().appendMessage(id, { role: "user", content: "Keep this" });
  render(<Composer />); const input = type("/new"); fireEvent.keyDown(input, { key: "Enter" });
  expect(useThreadStore.getState().activeThreadId).toBeNull();
  expect(useThreadStore.getState().threads).toHaveLength(1);
  expect(useThreadStore.getState().messagesByThread[id][0].content).toBe("Keep this");
});

// ── CHAT-TOOLS-FE (features/chat-tools-menu.feature) ───────────────────────
const workspaceTools = {
  workspace: { root: "D:\Development", name: "Development" },
  capabilities: {
    workspace: { root: "D:\Development", name: "Development" },
    provider_kind: "http" as const,
    tools: { discover: true, read: true, exec: true },
    preset: { read: true, exec: true },
    reason: "ok" as const,
    limits: { read_max_bytes: 262144, exec_timeout_s: 60, exec_max_timeout_s: 600, exec_output_max_bytes: 65536, max_tool_calls_per_turn: 8, max_reads_per_turn: 20 },
  },
  items: [
    { kind: "skill" as const, name: "harness", path: ".claude/skills/harness/SKILL.md", description: "Agile harness", source: "claude-skills" },
    { kind: "command" as const, name: "test", path: "frontend/package.json", argv: ["npm", "run", "test"], cwd: "frontend", source: "package-scripts" },
  ],
  readSkill: vi.fn(async () => "# harness draft"),
};
function ToolsComposer({ tools = workspaceTools, onPreset = vi.fn() }: { tools?: typeof workspaceTools | { workspace: null; capabilities: null; items: never[]; readSkill: () => Promise<string> }; onPreset?: (preset: unknown) => void }) {
  const [value, setValue] = useState("");
  const ref = useRef<HTMLTextAreaElement>(null);
  return <ChatComposer value={value} onChange={setValue} onSend={send} inputRef={ref} skills={{}} live={false} tools={tools} onPreset={onPreset} />;
}
it("Typing slash shows Command, Skill and Tool sections", () => {
  render(<ToolsComposer />); type("/");
  expect(screen.getByRole("option", { name: /\/new/ }).textContent).toContain("Command");
  expect(screen.getByRole("option", { name: /\/skill:harness/ }).textContent).toContain("inserir");
  expect(screen.getByRole("option", { name: /\/exec/ }).textContent).toContain("Tool");
});
it("Selecting a Skill inserts a draft and never executes", async () => {
  const onPreset = vi.fn();
  render(<ToolsComposer onPreset={onPreset} />); const input = type("/skill:harness");
  fireEvent.keyDown(input, { key: "Enter" });
  await screen.findByDisplayValue("# harness draft");
  expect(onPreset).not.toHaveBeenCalled(); expect(send).not.toHaveBeenCalled();
});
it("Selecting a Tool starts a run with a preset", () => {
  const onPreset = vi.fn();
  render(<ToolsComposer onPreset={onPreset} />); const input = type("/test");
  fireEvent.keyDown(input, { key: "Enter" });
  expect(onPreset).toHaveBeenCalledWith({ name: "exec", argv: ["npm", "run", "test"], cwd: "frontend" });
  expect(input.value).toBe("");
});
it("No workspace hides tools and says why", () => {
